#!/usr/bin/env bash
# Dataset library: every dataset is named by (seed, events, clicks), so it can be
# regenerated byte-identically on any machine instead of copied.
#   tools/datasets.sh tiny|medium|practice|full|heldout|dev   [DATA_ROOT]
# Clicks are always events/4 (the public dev set's ratio).
#   tiny     seeds 1-300, 1k-60k events     quick gate, edge-case dominated
#   medium   seeds 101-120, 2M events       reference at scale, profiling
#   practice seeds 201-203, 20M events      ~ hidden practice board size
#   full     seeds 301-303, 60M events      ~ final size; tuning
#   heldout  seeds 901-902, 60M events      never used for tuning
#   dev      seed 1, 1M events              the public dev set
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd)
GEN=${GEN:-$ROOT/bin/generate}
DATA=${2:-$ROOT/data}
mkdir -p "$DATA"
gen() {  # name seed events
  local dir="$DATA/$1"
  [ -f "$dir/manifest.json" ] && return 0
  "$GEN" --seed "$2" --events "$3" --clicks $(( $3 / 4 )) --output "$dir" >/dev/null
  echo "$dir"
}
case "${1:?set name}" in
  tiny)     for s in $(seq 1 300); do e=$(( 1000 + (s * 7919 % 59) * 1000 )); gen "tiny-s$s-e$e" "$s" "$e"; done ;;
  medium)   for s in $(seq 101 120); do gen "medium-s$s" "$s" 2000000; done ;;
  practice) for s in 201 202 203; do gen "practice-s$s" "$s" 20000000; done ;;
  full)     for s in 301 302 303; do gen "full-s$s" "$s" 60000000; done ;;
  heldout)  for s in 901 902; do gen "heldout-s$s" "$s" 60000000; done ;;
  dev)      gen dev-s1 1 1000000 ;;
  *) echo "unknown set: $1" >&2; exit 2 ;;
esac
